import os


def txtxml_upload_file(file_content, file_name, directory):
    base_directory = './Test/CWE-434_04'
    if not os.path.abspath(directory).startswith(base_directory):
        raise ValueError('Directory path is outside the allowed base directory')

    file_path = os.path.join(directory, file_name)
    try:
        with open(file_path, 'w') as file:
            file.write(file_content)
        return f'File {file_name} uploaded successfully to {directory}'
    except Exception as e:
        raise Exception(f'Failed to upload file: {e}')

